// Calculate renewal details for each policy
const policies = $input.all();
const today = new Date();

const enrichedPolicies = policies.map(policy => {
  const data = policy.json;
  const expirationDate = new Date(data['Expiration Date']);
  const daysUntilExpiration = Math.ceil((expirationDate - today) / (1000 * 60 * 60 * 24));

  // Determine notification stage
  let stage, urgency, recommendedAction;

  if (daysUntilExpiration >= 90) {
    stage = '90_day_notice';
    urgency = 'low';
    recommendedAction = 'Early notification - start shopping for quotes';
  } else if (daysUntilExpiration >= 60) {
    stage = '60_day_notice';
    urgency = 'low';
    recommendedAction = 'Review coverage needs, compare quotes';
  } else if (daysUntilExpiration >= 30) {
    stage = '30_day_notice';
    urgency = 'medium';
    recommendedAction = 'Schedule renewal consultation';
  } else if (daysUntilExpiration >= 14) {
    stage = '14_day_notice';
    urgency = 'high';
    recommendedAction = 'Finalize renewal decision';
  } else if (daysUntilExpiration >= 7) {
    stage = '7_day_urgent';
    urgency = 'urgent';
    recommendedAction = 'URGENT: Complete renewal immediately';
  } else if (daysUntilExpiration >= 3) {
    stage = '3_day_critical';
    urgency = 'critical';
    recommendedAction = 'CRITICAL: Coverage expires in 3 days';
  } else {
    stage = 'expiring_today';
    urgency = 'emergency';
    recommendedAction = 'EMERGENCY: Coverage expires TODAY';
  }

  // Calculate estimated annual premium increase (typical 3-7%)
  const currentPremium = parseFloat(data['Annual Premium']) || 0;
  const estimatedIncrease = currentPremium * 0.05; // 5% average
  const estimatedNewPremium = currentPremium + estimatedIncrease;

  // Calculate lifetime value
  const yearsAsCustomer = data['Years as Customer'] || 1;
  const lifetimeValue = currentPremium * yearsAsCustomer;

  return {
    json: {
      // Original data
      policyId: data['Policy ID'],
      policyNumber: data['Policy Number'],
      firstName: data['First Name'],
      lastName: data['Last Name'],
      email: data['Email'],
      phone: data['Phone'],
      policyType: data['Policy Type'],
      carrier: data['Carrier'],
      expirationDate: data['Expiration Date'],
      annualPremium: currentPremium,

      // Calculated fields
      daysUntilExpiration: daysUntilExpiration,
      stage: stage,
      urgency: urgency,
      recommendedAction: recommendedAction,
      estimatedIncrease: estimatedIncrease,
      estimatedNewPremium: estimatedNewPremium,
      lifetimeValue: lifetimeValue,
      yearsAsCustomer: yearsAsCustomer,

      // Agent assignment
      assignedAgent: data['Assigned Agent'] || 'Unassigned',
      agentEmail: data['Agent Email'] || 'admin@youragency.com',
      agentPhone: data['Agent Phone'] || '(123) 456-7890',

      // Status tracking
      renewalStatus: data['Renewal Status'] || 'pending',
      lastContactDate: data['Last Contact Date'] || null,
      renewalCallScheduled: data['Renewal Call Scheduled'] || false,

      // Timestamps
      processedAt: today.toISOString(),
      expirationFormatted: expirationDate.toLocaleDateString('en-US', { 
        weekday: 'long', 
        year: 'numeric', 
        month: 'long', 
        day: 'numeric' 
      })
    }
  };
});

return enrichedPolicies;

// Generate renewal ROI report
const policies = $input.all();

const summary = {
  totalPoliciesExpiring: policies.length,
  totalPremiumAtRisk: 0,
  totalLifetimeValue: 0,
  byUrgency: {
    low: 0,
    medium: 0,
    high: 0,
    urgent: 0,
    critical: 0,
    emergency: 0
  },
  byType: {},
  avgPremium: 0,
  estimatedRetentionRevenue: 0
};

policies.forEach(policy => {
  const data = policy.json;

  summary.totalPremiumAtRisk += data.annualPremium;
  summary.totalLifetimeValue += data.lifetimeValue;
  summary.byUrgency[data.urgency]++;

  if (!summary.byType[data.policyType]) {
    summary.byType[data.policyType] = 0;
  }
  summary.byType[data.policyType]++;
});

summary.avgPremium = summary.totalPremiumAtRisk / policies.length;
summary.estimatedRetentionRevenue = summary.totalPremiumAtRisk * 0.85; // 85% retention rate

return {
  json: {
    reportDate: new Date().toISOString(),
    summary: summary,
    policies: policies.map(p => p.json)
  }
};
